import json
import time

def process_payment(idempotency_key, amount):
    cache_key = f"idemp:{idempotency_key}"
    pending = "__idempotency_pending__"

    while True:
        acquired = redis.set(cache_key, pending, nx=True, ex=120)
        if acquired:
            receipt = stripe.Charge.create(amount=amount)
            redis.set(
                cache_key,
                json.dumps(receipt, separators=(",", ":")),
                ex=120,
            )
            return receipt

        cached = redis.get(cache_key)
        if cached is None:
            continue
        if isinstance(cached, (bytes, bytearray)):
            cached = cached.decode("utf-8")
        if isinstance(cached, str):
            if cached == pending:
                time.sleep(0.01)
                continue
            return json.loads(cached)
        return cached

